) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `certificates`;
CREATE TABLE `certificates` (
  `id` VARCHAR(36) PRIMARY KEY,
  `certificate_id` VARCHAR(100) NOT NULL UNIQUE,
